"""docs/TERMS-PROPOSAL.md is generated by i18n/terms_table.py: the 29 terms, the owner's decisions (T1) and the checks that
keep the Bulgarian texts in line with them (every term noun has its English bracket, no old wording is left)."""
from __future__ import annotations

import pathlib
import re

from i18n import glossary
from i18n import terms_table as tt


def test_the_proposal_file_is_up_to_date():
    assert tt.main(["--check"]) == 0, "run: cd server && ../.venv/bin/python -m i18n.terms_table"


def test_check_detects_drift_and_a_missing_file(tmp_path: pathlib.Path):
    out = tmp_path / "TERMS.md"
    assert tt.main(["--check"], out) == 1  # missing
    assert tt.main([], out) == 0 and tt.main(["--check"], out) == 0
    out.write_text(out.read_text(encoding="utf-8").replace("Recommendation", "Reco"), encoding="utf-8")
    assert tt.main(["--check"], out) == 1
    assert tt.main([], out) == 0 and tt.main(["--check"], out) == 0


def test_every_term_is_complete():
    seen = set()
    assert len(tt.TERMS) >= 25
    for t in tt.TERMS:
        assert t.en not in seen, t.en
        seen.add(t.en)
        assert 2 <= len(t.options) <= 3, t.en
        assert t.recommend.strip() and t.notes.strip() and t.wordings, t.en
        assert t.decision.startswith("DONE"), t.en  # T1: the owner accepted every row


def test_glossary_links_use_the_glossary_english():
    data = glossary.load()
    for t in tt.TERMS:
        if t.gloss:
            assert t.gloss in data, t.en
            first = t.en.split(" / ")[0].split(" (")[0]
            assert data[t.gloss]["en"].lower().startswith(first.lower()[:6]), (t.en, data[t.gloss]["en"])


def test_every_counted_wording_is_still_found():
    """A wording that no longer occurs anywhere was fixed (or its regex broke): drop it from the row."""
    corpus = tt._corpus()
    assert len(corpus) > 500
    for t in tt.TERMS:
        for label, regex in t.wordings:
            hits = tt.count(corpus, regex)
            assert any(hits.values()) or re.search(r"\bold\b", label), (t.en, label)  # an (old) wording may count 0 now


def test_the_document_has_a_row_per_term():
    text = pathlib.Path(tt.OUT).read_text(encoding="utf-8")
    assert f"{len(tt.TERMS)} terms." in text
    for n, t in enumerate(tt.TERMS, 1):
        assert text.count(f"| {n} | ") >= 1


def test_every_term_noun_in_a_bulgarian_text_has_its_english_bracket():
    """T1: wherever a Bulgarian text holds a term noun it also holds the English term in brackets (the first occurrence is
    enough; verbs and parts of other terms are not nouns). Exceptions are listed with a reason in COVERAGE_EXCEPTIONS."""
    assert tt.coverage_gaps() == []
    assert all(reason.strip() for reason in tt.COVERAGE_EXCEPTIONS.values())
    corpus = tt._corpus()
    for (row, where) in tt.COVERAGE_EXCEPTIONS:  # an exception that no longer applies must go
        assert any(f"{s}:{k}" == where for s, k, _t in corpus), where
        assert row in {t.en for t in tt.TERMS}


def test_no_old_wording_is_left():
    assert tt.forbidden_hits() == []


def test_the_checks_are_sensitive(monkeypatch):
    """A text with a noun and no bracket is reported, a bracket makes it pass, a forbidden word is reported."""
    corpus = [("msg", "x", "Изберете талант."), ("msg", "y", "Изберете талант (Feat)."), ("msg", "z", "Устойчивост на съпротива")]
    gaps = tt.coverage_gaps(corpus)
    assert ("Feat / Feats", "msg:x", "талант") in gaps and not [g for g in gaps if g[1] == "msg:y"]
    assert any(h[1] == "msg:z" for h in tt.forbidden_hits(corpus))
